div.script:
        // ============ EDIT THIS ONE LINE ============
        var API_BASE = "https://YOUR-NGROK-ID.ngrok-free.app";
        // ============================================

        var html = `





Chat







    Chat


      ＋


?
        User








What's on the agenda today?

Conversations save in this browser.














Local AI · messages stay on this device







Choose a name

Shown next to your messages. Stored only in this browser.



      Cancel
      Save




const API_BASE = "${API_BASE}";
const LS_USER = "mini_chat_user";
const LS_CONVOS = "mini_chat_convos";
const LS_ACTIVE = "mini_chat_active";
const $ = (s, el=document) => el.querySelector(s);
const messagesEl = $("#messages");
const emptyEl = $("#empty");
const promptEl = $("#prompt");
const sendBtn = $("#btn-send");
const chatArea = $("#chat-area");
const avatarEl = $("#avatar");
const nameLabel = $("#username-label");
const modal = $("#user-modal");
const nameInput = $("#name-input");
let username = localStorage.getItem(LS_USER) || "";
let sessionId = localStorage.getItem(LS_ACTIVE) || null;
let convos = (function(){ try { return JSON.parse(localStorage.getItem(LS_CONVOS)||"{}"); } catch(e){ return {}; } })();
let busy = false;
function saveConvos(){ localStorage.setItem(LS_CONVOS, JSON.stringify(convos)); }
function setActive(id){ sessionId = id; if(id) localStorage.setItem(LS_ACTIVE, id); else localStorage.removeItem(LS_ACTIVE); }
function applyUser(){
  if(username){ nameLabel.textContent = username; avatarEl.textContent = username.slice(0,2).toUpperCase(); avatarEl.classList.add("has-user"); }
  else { nameLabel.textContent = "User"; avatarEl.textContent = "?"; avatarEl.classList.remove("has-user"); }
}
applyUser();
function autoGrow(){
  promptEl.style.height = "auto";
  promptEl.style.height = Math.min(promptEl.scrollHeight, 200) + "px";
  sendBtn.disabled = !promptEl.value.trim() || busy;
}
promptEl.addEventListener("input", autoGrow);
promptEl.addEventListener("keydown", e => { if(e.key==="Enter" && !e.shiftKey){ e.preventDefault(); if(!sendBtn.disabled) send(); } });
$("#btn-send").addEventListener("click", send);
$("#btn-new").addEventListener("click", newChat);
$("#btn-user").addEventListener("click", () => { nameInput.value = username || ""; modal.classList.add("open"); nameInput.focus(); nameInput.select(); });
$("#btn-cancel").addEventListener("click", () => modal.classList.remove("open"));
$("#btn-save-name").addEventListener("click", saveName);
nameInput.addEventListener("keydown", e => { if(e.key==="Enter") saveName(); if(e.key==="Escape") modal.classList.remove("open"); });
modal.addEventListener("click", e => { if(e.target===modal) modal.classList.remove("open"); });
function saveName(){
  const v = nameInput.value.trim().slice(0,24);
  username = v || "";
  if(username) localStorage.setItem(LS_USER, username); else localStorage.removeItem(LS_USER);
  applyUser(); modal.classList.remove("open");
  document.querySelectorAll(".msg.user .msg-avatar").forEach(el => { el.textContent = username ? username.slice(0,2).toUpperCase() : "U"; });
}
function showChat(){ emptyEl.style.display = "none"; messagesEl.style.display = "flex"; }
function newChat(){
  setActive(null); messagesEl.innerHTML = ""; emptyEl.style.display = "flex"; messagesEl.style.display = "none";
  promptEl.value = ""; autoGrow(); promptEl.focus();
}
function addMessage(role, text){
  showChat();
  const row = document.createElement("div"); row.className = "msg " + role;
  const av = document.createElement("div"); av.className = "msg-avatar";
  if(role==="user"){ av.style.background = "var(--blue)"; av.textContent = username ? username.slice(0,2).toUpperCase() : "U"; }
  else { av.style.background = "#10a37f"; av.textContent = "AI"; }
  const body = document.createElement("div"); body.className = "msg-body"; body.textContent = text;
  row.appendChild(av); row.appendChild(body); messagesEl.appendChild(row);
  chatArea.scrollTop = chatArea.scrollHeight; return body;
}
function persistMessage(role, content){
  if(!sessionId){ sessionId = crypto.randomUUID(); setActive(sessionId); convos[sessionId] = { id: sessionId, title: content.slice(0,40), messages: [], ts: Date.now() }; }
  if(!convos[sessionId]) convos[sessionId] = { id: sessionId, title: content.slice(0,40), messages: [], ts: Date.now() };
  convos[sessionId].messages.push({ role, content }); convos[sessionId].ts = Date.now();
  if(role==="user" && convos[sessionId].messages.length===1) convos[sessionId].title = content.slice(0,48);
  saveConvos();
}
function restoreActive(){
  if(!sessionId || !convos[sessionId]) return;
  const msgs = convos[sessionId].messages || []; if(!msgs.length) return;
  messagesEl.innerHTML = ""; for(const m of msgs) addMessage(m.role, m.content); showChat();
}
restoreActive();
async function send(){
  const text = promptEl.value.trim(); if(!text || busy) return;
  busy = true; sendBtn.disabled = true;
  addMessage("user", text); persistMessage("user", text);
  promptEl.value = ""; autoGrow();
  const body = addMessage("assistant", ""); body.innerHTML = '';
  try {
    const res = await fetch(API_BASE + "/chat", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ message: text, session_id: sessionId, stream: true })
    });
    if(!res.ok) throw new Error("HTTP " + res.status);
    const reader = res.body.getReader(); const decoder = new TextDecoder();
    let full = "", buf = "";
    while(true){
      const { done, value } = await reader.read(); if(done) break;
      buf += decoder.decode(value, { stream: true });
      const parts = buf.split("\\n\\n"); buf = parts.pop();
      for(const part of parts){
        if(!part.startsWith("data: ")) continue;
        const data = part.slice(6); if(data==="[DONE]") continue;
        try { const j = JSON.parse(data); if(j.session_id){ sessionId = j.session_id; setActive(sessionId); continue; } } catch(_){}
        full += data; body.innerHTML = full + ''; chatArea.scrollTop = chatArea.scrollHeight;
      }
    }
    body.textContent = full || "(no response)"; persistMessage("assistant", body.textContent);
  } catch(err){
    body.textContent = "Connection failed — is the server + ngrok running?\\n" + err.message;
  } finally { busy = false; autoGrow(); promptEl.focus(); }
}
promptEl.focus();


`;

        var frame = document.getElementById("frame");
        var doc = frame.contentDocument || frame.contentWindow.document;
        doc.open();
        doc.write(html);
        doc.close();
